import pathlib,json,hashlib,gzip,subprocess
root=pathlib.Path.cwd();work=root/'.cache/validation/phase16';out=root/'docs/reference/phase16-integration';out.mkdir(exist_ok=True)
status=json.load(open(work/'full-status.json'));assert len(status)==4 and all(x['exit']==0 for x in status),status
stable=json.load(open(work/'source-stable.json'));assert stable['unchanged'],stable
source=json.load(open(work/'full-source-before.json'));tracked=set(subprocess.check_output(['git','ls-files'],text=True).splitlines());binaries={p:h for p,h in source.items() if p.startswith('native/build/')};unused={p:h for p,h in source.items() if p.startswith('docs/reference/svg-phase3-') and p not in tracked};inputs={p:h for p,h in source.items() if p not in binaries and p not in unused};assert len(source)==len(inputs)+len(binaries)+len(unused)
for p,h in source.items():assert hashlib.sha256((root/p).read_bytes()).hexdigest()==h,p
for name in ['full','reference','check','strict','focused-initial','puppeteer-initial','strict-initial']:
 data=(work/(name+'.log')).read_bytes();(out/(name+'.log.gz')).write_bytes(gzip.compress(data,mtime=0))
for name in ['run-validation.py','full-status.json','source-stable.json','full-source-before.json','full-source-after.json']:(out/name).write_bytes((work/name).read_bytes())
full=(work/'full.log').read_text();assert 'tests 1140' in full and 'pass 1140' in full and '60 checks passed' in full
reference=(work/'reference.log').read_text();referenceReport=json.loads(reference[reference.index('{\n  \"referenceSHA256\"'):]);assert len(referenceReport['checks'])==13 and all(x['passed'] for x in referenceReport['checks'])
report={'baseCommit':'74d85dfc1953be23cc14dd244e88c4bb3d84a41e','date':'2026-10-31','scope':'Independent realm CSS namespace, native-profile Canvas/Path2D state and real PNG encoding, UTF-8 value-byte quota and genuine context/origin Storage wrappers. No full browser/API/performance parity claim.','sourceSHA256':inputs,'nativeBuildArtifactSHA256':binaries,'unusedPreexistingReferenceSHA256':unused,'unchangedObservedInputs':len(source),'committedSourceAndReferenceInputs':len(inputs),'checks':status,'counts':{'javascript':1140,'purescript':60,'nativeDifferentialGroups':13,'focusedCombined':34},'focusedCrossRuntime':{'CSS':'8/8 each Node24.19.0,24.22.1,26.13.0','Storage':'10/10 each exact Node version; separate stress29/30 has one heap deadline','Canvas':'earlier16/16 each exact Node; later stress epochs have retained readiness/heap/screenshot failures; final Root combined and full checks are this graph'},'limits':['534-name inspected CSS vocabulary; full CSS parsing and @supports cascade incomplete','Native-profile Canvas drawing has no raster output; real transparent reads and independent1x1 PNG encoding only','Storage key order, legacy reflection, protocol Proxy classification and opaque child initialization differ','Full default48/455-registration/WPT cohort is not rerun at this graph; six relevant unchanged fixtures have separate Native positive controls','MediaData, tracks, permissions, URLPattern and wider API work remains isolated until separately integrated','No browser isolation or Native performance equivalence claim'],'artifacts':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in out.iterdir() if p.is_file() and p.name!='validation.json'}}
(out/'validation.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'sourceAndReferenceInputs':len(inputs),'observedInputs':len(source),'counts':report['counts']}))
